				mx2 = mx1;
				mx1 = mtHeight;
			}else if(mx2 < mtHeight){
				mx3 = mx2;
				mx2 = mtHeight;
			}else if(mx3 < mtHeight){
				mx3 = mtHeight;
			}

			}
		System.out.printf("%d\n%d\n%d\n", mx1, mx2, mx3);
	}
